import{_ as o,a0 as i,w as p,s as l,ao as d,I as a,x as e,a1 as r,A as n}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const f=JSON.parse('{"title":"Linux Systemd —— 在RHEL/CentOS 7中启动/停止/重启服务 | LCTT x X-CMD","titleTemplate":false,"description":"Linux Systemd —— 在RHEL/CentOS 7中启动/停止/重启服务 | LCTT (201409) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Linux Systemd —— 在RHEL/CentOS 7中启动/停止/重启服务 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Linux Systemd —— 在RHEL/CentOS 7中启动/停止/重启服务 | LCTT (201409) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201409/20140819 Linux Systemd--Start or Stop or Restart Services in RHEL or CentOS 7","title":"Linux Systemd —— 在RHEL/CentOS 7中启动/停止/重启服务","tag":"201409","desc":""},"relativePath":"201409/20140819 Linux Systemd--Start or Stop or Restart Services in RHEL or CentOS 7.md","filePath":"[post].md"}'),m={name:"201409/20140819 Linux Systemd--Start or Stop or Restart Services in RHEL or CentOS 7.md"};function u(c,t,S,y,x,L){const s=i("Link");return p(),l("div",null,[t[13]||(t[13]=d(`<h1 id="linux-systemd-——-在rhel-centos-7中启动-停止-重启服务" tabindex="-1">Linux Systemd —— 在RHEL/CentOS 7中启动/停止/重启服务 <a class="header-anchor" href="#linux-systemd-——-在rhel-centos-7中启动-停止-重启服务" aria-label="Permalink to “Linux Systemd —— 在RHEL/CentOS 7中启动/停止/重启服务”">​</a></h1><p>RHEL/CentOS 7.0中一个最主要的改变，就是切换到了<strong>systemd</strong>。它用于替代红帽企业版Linux前任版本中的SysV和Upstart，对系统和服务进行管理。systemd兼容SysV和Linux标准组的启动脚本。</p><p><strong>Systemd</strong>是一个Linux操作系统下的系统和服务管理器。它被设计成向后兼容SysV启动脚本，并提供了大量的特性，如开机时平行启动系统服务，按需启动守护进程，支持系统状态快照，或者基于依赖的服务控制逻辑。</p><p>先前的使用SysV初始化或Upstart的红帽企业版Linux版本中，使用位于/etc/rc.d/init.d/目录中的bash初始化脚本进行管理。而在RHEL 7/CentOS 7中，这些启动脚本被服务单元取代了。服务单元以.service文件扩展结束，提供了与初始化脚本同样的用途。要查看、启动、停止、重启、启用或者禁用系统服务，你要使用systemctl来代替旧的service命令。</p><blockquote><p>注：为了向后兼容，旧的service命令在CentOS 7中仍然可用，它会重定向所有命令到新的systemctl工具。</p></blockquote><h3 id="使用systemctl来启动-停止-重启服务" tabindex="-1">使用systemctl来启动/停止/重启服务 <a class="header-anchor" href="#使用systemctl来启动-停止-重启服务" aria-label="Permalink to “使用systemctl来启动/停止/重启服务”">​</a></h3><p>要启动一个服务，你需要使用如下命令：</p><pre><code># systemctl start httpd.service
</code></pre><p>这会启动httpd服务，就我们而言，Apache HTTP服务器。</p><p>要停掉它，需要以root身份使用该命令：</p><pre><code># systemctl stop httpd.service
</code></pre><p>要重启，你可以使用restart选项，如果服务在运行中，它将重启服务；如果服务不在运行中，它将会启动。你也可以使用try-start选项，它只会在服务已经在运行中的时候重启服务。同时，reload选项你也可以有，它会重新加载配置文件。</p><pre><code># systemctl restart httpd.service
# systemctl try-restart httpd.service
# systemctl reload httpd.service
</code></pre><p>我们例子中的命令看起来会像下面这样：</p><p><img src="http://linoxide.com/wp-content/uploads/2014/08/systemctl-start-stop-restart.gif" alt="systemctl start-stop-restart"></p><h3 id="检查服务状态" tabindex="-1">检查服务状态 <a class="header-anchor" href="#检查服务状态" aria-label="Permalink to “检查服务状态”">​</a></h3><p>要检查服务状态，你可以使用status选项，看这里：</p><pre><code># systemctl status httpd.service
</code></pre><p>输出结果就像这样：</p><p><img src="http://linoxide.com/wp-content/uploads/2014/08/systemctl-status.gif" alt="systemctl status"></p><p>它会告诉你运行中的服务的方方面面。</p><h3 id="使用启用-禁用服务来控制开机启动" tabindex="-1">使用启用/禁用服务来控制开机启动 <a class="header-anchor" href="#使用启用-禁用服务来控制开机启动" aria-label="Permalink to “使用启用/禁用服务来控制开机启动”">​</a></h3><p>你也可以使用enable/disable选项来控制一个服务是否开机启动，命令如下：</p><pre><code># systemctl enable httpd.service
# systemctl disable httpd.service
</code></pre><p>输出结果看这里：</p><p><img src="http://linoxide.com/wp-content/uploads/2014/08/systemctl-enable.gif" alt="systemctl-enable"></p><p>虽然在过去的几年中，对systemd的采用饱受争议，然而大多数主流发行版都已经逐渐采用或打算在下一个发行版中采用它。所以，它是一个有用的工具，我们需要好好熟悉它。</p><hr>`,28)),a("p",null,[t[1]||(t[1]=e("via: ",-1)),r(s,{href:"http://linoxide.com/linux-command/start-stop-services-systemd/"},{default:n(()=>[...t[0]||(t[0]=[e("http://linoxide.com/linux-command/start-stop-services-systemd/",-1)])]),_:1})]),a("p",null,[t[5]||(t[5]=e("作者：",-1)),r(s,{href:"http://linoxide.com/author/adriand/"},{default:n(()=>[...t[2]||(t[2]=[e("Adrian Dinu",-1)])]),_:1}),t[6]||(t[6]=e(" 译者：",-1)),r(s,{href:"https://github.com/GOLinux"},{default:n(()=>[...t[3]||(t[3]=[e("GOLinux",-1)])]),_:1}),t[7]||(t[7]=e(" 校对：",-1)),r(s,{href:"https://github.com/carolinewuyan"},{default:n(()=>[...t[4]||(t[4]=[e("Caroline",-1)])]),_:1})]),a("p",null,[t[10]||(t[10]=e("本文由 ",-1)),r(s,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...t[8]||(t[8]=[e("LCTT",-1)])]),_:1}),t[11]||(t[11]=e(" 原创翻译，",-1)),r(s,{href:"http://linux.cn/"},{default:n(()=>[...t[9]||(t[9]=[e("Linux中国",-1)])]),_:1}),t[12]||(t[12]=e(" 荣誉推出",-1))])])}const T=o(m,[["render",u]]);export{f as __pageData,T as default};
